@property.deleter : deletes a property. Here is an example:
class Person:
def __init__(self, name):
        self._name = name
@property
def name(self):
# Getter
return self._name
@name.setter
def name(self, new_name):
# Setter
        self._name = new_name 
p = Person("Alice")
print(p.name)
# Alice (calls the getter)
p.name = "Bob"
# Calls the setter
print(p.name)
# Bob
